/**
 * Phase 0 database schema: identity, classes, consent, projects and audit.
 *
 * Design rules (see docs/architecture/database.md for the full model):
 * - Learners are pseudonymous. A learner row never holds an email, phone
 *   number or real name; classmates and teachers see a per-class pseudonym.
 * - Nothing is hard-deleted by the application; rows are archived, revoked or
 *   soft-deleted and purged later by a retention job.
 * - Primary keys are UUIDv7 (time-ordered, generated by PostgreSQL 18).
 */
import { sql } from 'drizzle-orm';
import {
  bigint,
  boolean,
  check,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  smallint,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

const id = () =>
  uuid('id')
    .primaryKey()
    .default(sql`uuidv7()`);
const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
const at = (name: string) => timestamp(name, { withTimezone: true });

export const accountKind = pgEnum('account_kind', ['adult', 'learner']);
export const platformRole = pgEnum('platform_role', [
  'platform_admin',
  'content_author',
  'content_reviewer',
]);
export const schoolRole = pgEnum('school_role', ['school_admin', 'teacher', 'student', 'guardian']);
export const consentScope = pgEnum('consent_scope', ['platform_use', 'ai_tutor', 'gallery']);
export const consentGrantor = pgEnum('consent_grantor', ['guardian', 'school']);

/**
 * pending: applied, waiting for the lab's owner; active: working; suspended:
 * stopped by the owner for now (its classes cannot be joined and its staff
 * cannot act for it). A closed school has `archived_at` set instead.
 */
export const schoolStatus = pgEnum('school_status', ['pending', 'active', 'suspended']);

export const schools = pgTable('schools', {
  id: id(),
  name: text('name').notNull(),
  /** Educational Institute Identification Number, when the school has one. */
  eiin: text('eiin').unique(),
  district: text('district'),
  status: schoolStatus('status').notNull().default('active'),
  createdAt: createdAt(),
  archivedAt: at('archived_at'),
});

export const users = pgTable(
  'users',
  {
    id: id(),
    kind: accountKind('kind').notNull(),
    displayName: text('display_name').notNull(),
    email: text('email'),
    passwordHash: text('password_hash'),
    /**
     * A learner signs in with a key the lab gave them (long and random), kept as
     * its SHA-256 so that it can be found; adults have none.
     */
    signInKeyHash: text('sign_in_key_hash').unique(),
    /**
     * A learner with an account of their own, outside any school, signs in with
     * a name they chose (letters, digits, dot, dash, underscore) and a password.
     * It is not contact information; their guardian's email is kept apart.
     */
    username: text('username'),
    /** When the adult opened the link sent to their email. */
    emailVerifiedAt: at('email_verified_at'),
    platformRole: platformRole('platform_role'),
    locale: text('locale').notNull().default('bn'),
    createdAt: createdAt(),
    /** Closed for good (by its school, or by the lab's owner); its data waits for the retention job. */
    deactivatedAt: at('deactivated_at'),
    /** Stopped for now by the lab's owner, and can be started again. */
    suspendedAt: at('suspended_at'),
    /**
     * When the retention job emptied this closed account of personal data. The
     * row stays, as other records point to it; its name and contact are gone.
     */
    erasedAt: at('erased_at'),
  },
  (t) => [
    uniqueIndex('users_email_unique').on(sql`lower(${t.email})`),
    uniqueIndex('users_username_unique').on(sql`lower(${t.username})`),
    check('users_username_is_for_learners', sql`${t.kind} = 'learner' OR ${t.username} IS NULL`),
    check('users_learner_has_no_contact_details', sql`${t.kind} = 'adult' OR ${t.email} IS NULL`),
    check(
      'users_learner_has_no_platform_role',
      sql`${t.kind} = 'adult' OR ${t.platformRole} IS NULL`,
    ),
  ],
);

export const schoolMemberships = pgTable(
  'school_memberships',
  {
    id: id(),
    schoolId: uuid('school_id')
      .notNull()
      .references(() => schools.id, { onDelete: 'restrict' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'restrict' }),
    role: schoolRole('role').notNull(),
    createdAt: createdAt(),
    endedAt: at('ended_at'),
  },
  (t) => [
    unique('school_memberships_unique').on(t.schoolId, t.userId, t.role),
    index('school_memberships_user_idx').on(t.userId),
  ],
);

export const classes = pgTable(
  'classes',
  {
    id: id(),
    schoolId: uuid('school_id')
      .notNull()
      .references(() => schools.id, { onDelete: 'restrict' }),
    teacherId: uuid('teacher_id')
      .notNull()
      .references(() => users.id, { onDelete: 'restrict' }),
    name: text('name').notNull(),
    grade: smallint('grade').notNull(),
    /** Hash of the code learners type to join. The code itself is never stored. */
    joinCodeHash: text('join_code_hash').unique(),
    joinCodeExpiresAt: at('join_code_expires_at'),
    createdAt: createdAt(),
    archivedAt: at('archived_at'),
  },
  (t) => [
    index('classes_school_idx').on(t.schoolId),
    index('classes_teacher_idx').on(t.teacherId),
    check('classes_grade_range', sql`${t.grade} BETWEEN 6 AND 12`),
  ],
);

/** Pseudonymous learner access: which learner sits in which class, under which pseudonym. */
export const classEnrollments = pgTable(
  'class_enrollments',
  {
    id: id(),
    classId: uuid('class_id')
      .notNull()
      .references(() => classes.id, { onDelete: 'restrict' }),
    learnerId: uuid('learner_id')
      .notNull()
      .references(() => users.id, { onDelete: 'restrict' }),
    pseudonym: text('pseudonym').notNull(),
    createdAt: createdAt(),
    revokedAt: at('revoked_at'),
  },
  (t) => [
    unique('class_enrollments_learner_unique').on(t.classId, t.learnerId),
    unique('class_enrollments_pseudonym_unique').on(t.classId, t.pseudonym),
    index('class_enrollments_learner_idx').on(t.learnerId),
  ],
);

export const consentRecords = pgTable(
  'consent_records',
  {
    id: id(),
    learnerId: uuid('learner_id')
      .notNull()
      .references(() => users.id, { onDelete: 'restrict' }),
    schoolId: uuid('school_id').references(() => schools.id, { onDelete: 'restrict' }),
    scope: consentScope('scope').notNull(),
    // schoolId is null for a learner on their own, whose guardian gave the permission.
    grantedBy: consentGrantor('granted_by').notNull(),
    /** Version of the policy text that was agreed to. */
    policyVersion: text('policy_version').notNull(),
    /** Staff member who recorded the consent. */
    recordedBy: uuid('recorded_by')
      .notNull()
      .references(() => users.id, { onDelete: 'restrict' }),
    grantedAt: at('granted_at').notNull().defaultNow(),
    revokedAt: at('revoked_at'),
  },
  (t) => [
    index('consent_records_learner_idx').on(t.learnerId, t.scope),
    check(
      'consent_records_school_or_guardian',
      sql`${t.grantedBy} = 'guardian' OR ${t.schoolId} IS NOT NULL`,
    ),
  ],
);

export const projects = pgTable(
  'projects',
  {
    id: id(),
    ownerId: uuid('owner_id')
      .notNull()
      .references(() => users.id, { onDelete: 'restrict' }),
    title: text('title').notNull(),
    createdAt: createdAt(),
    updatedAt: at('updated_at').notNull().defaultNow(),
    deletedAt: at('deleted_at'),
  },
  (t) => [index('projects_owner_idx').on(t.ownerId, t.updatedAt)],
);

/** Immutable snapshots of a project. Offline sync appends versions; it never rewrites one. */
export const projectVersions = pgTable(
  'project_versions',
  {
    id: id(),
    projectId: uuid('project_id')
      .notNull()
      .references(() => projects.id, { onDelete: 'cascade' }),
    version: integer('version').notNull(),
    /** `schemaVersion` of the circuit document, for server-side migrations. */
    schemaVersion: integer('schema_version').notNull(),
    document: jsonb('document').notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    unique('project_versions_unique').on(t.projectId, t.version),
    check('project_versions_positive', sql`${t.version} > 0`),
  ],
);

/** Append-only record of security-relevant actions. Holds identifiers, never content. */
export const auditLogs = pgTable(
  'audit_logs',
  {
    id: bigint('id', { mode: 'bigint' }).primaryKey().generatedAlwaysAsIdentity(),
    occurredAt: at('occurred_at').notNull().defaultNow(),
    actorId: uuid('actor_id').references(() => users.id, { onDelete: 'set null' }),
    schoolId: uuid('school_id').references(() => schools.id, { onDelete: 'set null' }),
    action: text('action').notNull(),
    targetType: text('target_type'),
    targetId: text('target_id'),
    metadata: jsonb('metadata'),
  },
  (t) => [
    index('audit_logs_time_idx').on(t.occurredAt),
    index('audit_logs_actor_idx').on(t.actorId, t.occurredAt),
  ],
);

/**
 * A signed-in device. The token itself lives only in the browser's cookie; the
 * database keeps its SHA-256, so a copy of the database cannot sign anyone in.
 */
export const sessions = pgTable(
  'sessions',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'restrict' }),
    tokenHash: text('token_hash').notNull().unique(),
    createdAt: createdAt(),
    expiresAt: at('expires_at').notNull(),
    revokedAt: at('revoked_at'),
    /** "Keep me signed in on this device": otherwise the cookie ends with the browser. */
    persistent: boolean('persistent').notNull().default(true),
  },
  (t) => [index('sessions_user_idx').on(t.userId)],
);

/** A lesson a teacher has set for a class, with a date to finish it by if they gave one. */
export const lessonAssignments = pgTable(
  'lesson_assignments',
  {
    id: id(),
    classId: uuid('class_id')
      .notNull()
      .references(() => classes.id, { onDelete: 'restrict' }),
    /** The lesson's id, as in packages/lessons (e.g. "push-button"). */
    lessonId: text('lesson_id').notNull(),
    dueAt: at('due_at'),
    createdAt: createdAt(),
    removedAt: at('removed_at'),
  },
  (t) => [index('lesson_assignments_class_idx').on(t.classId)],
);

export const progressOutcome = pgEnum('progress_outcome', ['step-done', 'lesson-done']);

/**
 * What a learner did in a lesson, as the lab reported it. Append-only. The
 * event's id is made on the device, so an event sent twice (after being
 * offline) is kept once.
 */
export const progressEvents = pgTable(
  'progress_events',
  {
    id: id(),
    learnerId: uuid('learner_id')
      .notNull()
      .references(() => users.id, { onDelete: 'restrict' }),
    lessonId: text('lesson_id').notNull(),
    step: integer('step').notNull(),
    outcome: progressOutcome('outcome').notNull(),
    clientEventId: uuid('client_event_id').notNull().unique(),
    occurredAt: at('occurred_at').notNull(),
    receivedAt: createdAt(),
  },
  (t) => [
    index('progress_events_learner_idx').on(t.learnerId, t.lessonId),
    check('progress_events_step_positive', sql`${t.step} >= 0`),
  ],
);

/**
 * A school admin's invitation for another teacher to join the school. The code
 * is shown to the admin once and kept only as a hash; it works once, for a week.
 */
export const teacherInvites = pgTable(
  'teacher_invites',
  {
    id: id(),
    schoolId: uuid('school_id')
      .notNull()
      .references(() => schools.id, { onDelete: 'restrict' }),
    createdBy: uuid('created_by')
      .notNull()
      .references(() => users.id, { onDelete: 'restrict' }),
    codeHash: text('code_hash').notNull().unique(),
    expiresAt: at('expires_at').notNull(),
    acceptedBy: uuid('accepted_by').references(() => users.id, { onDelete: 'restrict' }),
    acceptedAt: at('accepted_at'),
    revokedAt: at('revoked_at'),
    createdAt: createdAt(),
  },
  (t) => [index('teacher_invites_school_idx').on(t.schoolId)],
);

/**
 * The guardian of a learner under 18 with an account of their own: the email
 * that approved the account and that receives its password resets. Kept apart
 * from the learner's row, which never holds contact details.
 */
export const guardianLinks = pgTable(
  'guardian_links',
  {
    id: id(),
    learnerId: uuid('learner_id')
      .notNull()
      .references(() => users.id, { onDelete: 'restrict' }),
    email: text('email').notNull(),
    /** When the guardian approved the account through the emailed link. */
    approvedAt: at('approved_at'),
    createdAt: createdAt(),
    revokedAt: at('revoked_at'),
  },
  (t) => [index('guardian_links_learner_idx').on(t.learnerId)],
);

export const emailTokenPurpose = pgEnum('email_token_purpose', [
  'verify-email',
  'approve-learner',
  'reset-password',
  'close-account',
]);

/** A one-time link sent by email: only its SHA-256 is kept. */
export const emailTokens = pgTable(
  'email_tokens',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'restrict' }),
    purpose: emailTokenPurpose('purpose').notNull(),
    /** The address it went to. */
    email: text('email').notNull(),
    tokenHash: text('token_hash').notNull().unique(),
    expiresAt: at('expires_at').notNull(),
    usedAt: at('used_at'),
    createdAt: createdAt(),
  },
  (t) => [index('email_tokens_user_idx').on(t.userId, t.purpose)],
);
